import java.lang.annotation.*;
import java.lang.reflect.*;

public class Main {
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface PostConstruct {}

    interface InitializingBean { void afterPropertiesSet(); }

    static class Bean implements InitializingBean {
        StringBuilder log = new StringBuilder();
        @PostConstruct void init1() { log.append("postConstruct;"); }
        public void afterPropertiesSet() { log.append("initializingBean;"); }
        void customInit() { log.append("initMethod;"); }
        String log() { return log.toString(); }
    }

    public static void main(String[] args) throws Exception {
        Bean b = new Bean();
        for (Method m : Bean.class.getDeclaredMethods()) {
            if (m.isAnnotationPresent(PostConstruct.class)) m.invoke(b);
        }
        b.afterPropertiesSet();
        Bean.class.getDeclaredMethod("customInit").invoke(b);
        System.out.println(b.log());
    }
}
